            ["story_found"] = new[] { "You found a page from the previous tenants' diary", "Найдена страница из дневника прежних жильцов", "Бұрынғы тұрғындардың күнделігінен бет табылды", "Encontraste una página del diario de los inquilinos anteriores", "Você encontrou uma página do diário dos antigos moradores" },
