            ["story_locked"] = new[] { "Survive another night to find the next page.", "Переживи ещё одну ночь, чтобы найти следующую страницу.", "Келесі бетті табу үшін тағы бір түн аман қал.", "Sobrevive otra noche para encontrar la siguiente página.", "Sobreviva mais uma noite para achar a próxima página." },
