            ["story_1"] = new[] { "March 3. We moved in today. The house is cheap — too cheap. The old woman next door turned away when she saw our truck and quickly went inside.", "3 марта. Сегодня переехали. Дом дешёвый — слишком дешёвый. Соседка-старушка, увидев нашу машину, отвернулась и быстро ушла в дом.", "3 наурыз. Бүгін көшіп келдік. Үй арзан — тым арзан. Көрші кемпір біздің көлікті көріп, теріс бұрылды да, үйіне тез кіріп кетті.", "3 de marzo. Hoy nos mudamos. La casa es barata, demasiado barata. La anciana de al lado se dio la vuelta al ver nuestro camión y entró deprisa.", "3 de março. Hoje nos mudamos. A casa é barata — barata demais. A velha vizinha virou o rosto ao ver nosso caminhão e entrou depressa." },
            ["story_2"] = new[] { "March 9. Knocking in the walls at night. Arman says it's the pipes. Pipes don't knock exactly three times.", "9 марта. Ночью стук в стенах. Арман говорит, что это трубы. Трубы не стучат ровно три раза.", "9 наурыз. Түнде қабырғада тықыл. Арман бұл құбыр дейді. Құбыр дәл үш рет тықылдамайды.", "9 de marzo. Golpes en las paredes de noche. Arman dice que son las tuberías. Las tuberías no golpean exactamente tres veces.", "9 de março. Batidas nas paredes à noite. Arman diz que são os canos. Canos não batem exatamente três vezes." },
            ["story_3"] = new[] { "March 14. Under the old paint on every windowsill — a line of salt. Someone kept something out of this house. Or inside it.", "14 марта. Под старой краской на каждом подоконнике — полоска соли. Кто-то не пускал что-то в этот дом. Или не выпускал.", "14 наурыз. Әр терезе алдындағы ескі бояудың астында — тұз сызығы. Біреу бір нәрсені бұл үйге кіргізбеген. Әлде шығармаған.", "14 de marzo. Bajo la pintura vieja de cada alféizar hay una línea de sal. Alguien no dejaba entrar algo en esta casa. O no lo dejaba salir.", "14 de março. Sob a tinta velha de cada parapeito, uma linha de sal. Alguém impedia algo de entrar nesta casa. Ou de sair." },
            ["story_4"] = new[] { "March 20. Our daughter says a woman with long hair sits by her bed and laughs quietly. I put a needle under her pillow, the way my grandmother taught me.", "20 марта. Дочь говорит, что у её кровати сидит женщина с длинными волосами и тихо смеётся. Я положила ей под подушку иглу, как учила бабушка.", "20 наурыз. Қызым төсегінің жанында шашы ұзын әйел отырып, ақырын күледі дейді. Әжем үйреткендей, жастығының астына ине салдым.", "20 de marzo. Nuestra hija dice que una mujer de pelo largo se sienta junto a su cama y se ríe bajito. Le puse una aguja bajo la almohada, como me enseñó mi abuela.", "20 de março. Nossa filha diz que uma mulher de cabelo comprido senta perto da cama e ri baixinho. Coloquei uma agulha sob o travesseiro, como minha avó ensinou." },
            ["story_5"] = new[] { "April 2. The thermometer in the hallway showed minus four. In April. That night the radio caught a voice. It said our names.", "2 апреля. Термометр в коридоре показал минус четыре. В апреле. Ночью радио поймало голос. Он называл наши имена.", "2 сәуір. Дәліздегі термометр минус төртті көрсетті. Сәуірде. Түнде радио бір дауысты ұстады. Ол біздің аттарымызды атады.", "2 de abril. El termómetro del pasillo marcó cuatro bajo cero. En abril. Esa noche la radio captó una voz. Decía nuestros nombres.", "2 de abril. O termômetro do corredor marcou quatro abaixo de zero. Em abril. À noite o rádio pegou uma voz. Ela dizia nossos nomes." },
            ["story_6"] = new[] { "April 11. The neighbor finally spoke. Before us there were five families. All left within a month. One never left at all.", "11 апреля. Соседка наконец заговорила. До нас тут жили пять семей. Все уехали в первый же месяц. Одна не уехала вовсе.", "11 сәуір. Көрші ақыры сөйледі. Бізге дейін мұнда бес отбасы тұрған. Бәрі бірінші айда-ақ көшіп кеткен. Біреуі мүлде кетпеген.", "11 de abril. La vecina por fin habló. Antes que nosotros vivieron aquí cinco familias. Todas se fueron el primer mes. Una nunca se fue.", "11 de abril. A vizinha finalmente falou. Antes de nós, cinco famílias moraram aqui. Todas saíram no primeiro mês. Uma nunca saiu." },
            ["story_7"] = new[] { "April 25. There is a door in the basement that is not on the plans. Behind it, it is cold. Behind it, something breathes.", "25 апреля. В подвале есть дверь, которой нет на плане. За ней холодно. За ней кто-то дышит.", "25 сәуір. Жертөледе жоспарда жоқ есік бар. Оның арғы жағы суық. Арғы жағында біреу дем алып тұр.", "25 de abril. En el sótano hay una puerta que no está en los planos. Detrás hace frío. Detrás algo respira.", "25 de abril. No porão há uma porta que não está na planta. Atrás dela faz frio. Atrás dela algo respira." },
            ["story_8"] = new[] { "May 6. I opened it. A well, sealed with iron and salt. Something was locked inside. The seal was broken long before us.", "6 мая. Я открыла её. Колодец, запечатанный железом и солью. В нём что-то заперли. Печать сломали задолго до нас.", "6 мамыр. Мен оны аштым. Темір мен тұзбен бітелген құдық. Ішіне бір нәрсені қамап қойған. Мөрді бізден әлдеқайда бұрын бұзған.", "6 de mayo. La abrí. Un pozo sellado con hierro y sal. Algo estaba encerrado dentro. El sello se rompió mucho antes que nosotros.", "6 de maio. Eu abri. Um poço selado com ferro e sal. Algo estava preso lá dentro. O selo foi quebrado muito antes de nós." },
            ["story_9"] = new[] { "May 13. They come one at a time. Each fears something different. I am writing everything down — whoever lives here next will need this journal.", "13 мая. Они приходят по одной. Каждая боится своего. Я записываю всё — тому, кто будет жить здесь после нас, понадобится этот дневник.", "13 мамыр. Олар бір-бірлеп келеді. Әрқайсысы әртүрлі нәрседен қорқады. Бәрін жазып жүрмін — бізден кейін мұнда тұратын адамға бұл күнделік керек болады.", "13 de mayo. Vienen de una en una. Cada una teme algo distinto. Lo apunto todo: quien viva aquí después necesitará este diario.", "13 de maio. Elas vêm uma de cada vez. Cada uma teme algo diferente. Estou anotando tudo — quem morar aqui depois vai precisar deste diário." },
            ["story_10"] = new[] { "Last page. If you are reading this, the house has chosen you. Keep the ward. Don't let them out. Dawn always comes — if you live to see it.", "Последняя страница. Если ты это читаешь — дом выбрал тебя. Храни защиту. Не выпускай их. Рассвет приходит всегда — если ты до него доживёшь.", "Соңғы бет. Егер мұны оқып отырсаң — үй сені таңдады. Қорғанысты сақта. Оларды шығарма. Таң әрқашан атады — егер оған дейін аман қалсаң.", "Última página. Si estás leyendo esto, la casa te ha elegido. Mantén la protección. No las dejes salir. El amanecer siempre llega, si vives para verlo.", "Última página. Se você está lendo isto, a casa escolheu você. Mantenha a proteção. Não as deixe sair. O amanhecer sempre chega — se você viver para vê-lo." },
            ["m.NewMoon.name"] = new[] { "New moon", "Новолуние", "Жаңа ай", "Luna nueva", "Lua nova" },
            ["m.NewMoon.desc"] = new[] { "Darker than usual. The lantern drains twice as fast.", "Темнее обычного. Фонарь садится вдвое быстрее.", "Әдеттегіден қараңғы. Шам екі есе тез отырады.", "Más oscuro que de costumbre. La linterna se gasta el doble de rápido.", "Mais escuro que o normal. A lanterna gasta duas vezes mais rápido." },
            ["m.Storm.name"] = new[] { "Storm", "Гроза", "Найзағай", "Tormenta", "Tempestade" },
            ["m.Storm.desc"] = new[] { "Lightning and thunder. Thunder hides your noise for a moment.", "Молнии и гром. Гром ненадолго скрывает твой шум.", "Найзағай мен күн күркіреуі. Күн күркіресе, сенің шуың біраз уақыт білінбейді.", "Relámpagos y truenos. El trueno oculta tu ruido un momento.", "Relâmpagos e trovões. O trovão esconde seu barulho por um momento." },
            ["m.FullMoon.name"] = new[] { "Full moon", "Полнолуние", "Толған ай", "Luna llena", "Lua cheia" },
            ["m.FullMoon.desc"] = new[] { "The entity grows angry one and a half times faster.", "Сущность злится в полтора раза быстрее.", "Тылсым күш бір жарым есе тез ашуланады.", "La entidad se enfada una vez y media más rápido.", "A entidade se irrita uma vez e meia mais rápido." },
            ["m.Silence.name"] = new[] { "Dead silence", "Мёртвая тишина", "Өлі тыныштық", "Silencio sepulcral", "Silêncio mortal" },
            ["m.Silence.desc"] = new[] { "Not a creak in the house — and it hears you better.", "В доме ни скрипа — и она слышит тебя лучше.", "Үйде бірде-бір сықыр жоқ — әрі ол сені жақсырақ естиді.", "Ni un crujido en la casa, y te oye mejor.", "Nem um rangido na casa — e ela ouve você melhor." },
            ["xp_bonus"] = new[] { "×{0} XP tonight", "×{0} опыта этой ночью", "Бүгін түнде ×{0} тәжірибе", "×{0} XP esta noche", "×{0} XP esta noite" },
            ["daily"] = new[] { "DAILY CASE", "ДЕЛО ДНЯ", "КҮН ІСІ", "CASO DEL DÍA", "CASO DO DIA" },
            ["daily_intro"] = new[] { "Daily case. The same entity comes to every player today.\nSolve it on the first try — double XP.", "Дело дня. Сегодня ко всем игрокам приходит одна и та же сущность.\nРаскрой с первого раза — двойной опыт.", "Күн ісі. Бүгін барлық ойыншыға бір тылсым күш келеді.\nБірінші реттен шеш — екі есе тәжірибе.", "Caso del día. Hoy la misma entidad visita a todos los jugadores.\nResuélvelo a la primera: doble XP.", "Caso do dia. Hoje a mesma entidade visita todos os jogadores.\nResolva de primeira — XP em dobro." },
            ["daily_done"] = new[] { "Daily case solved! Streak: {0}", "Дело дня раскрыто! Серия: {0}", "Күн ісі шешілді! Серия: {0}", "¡Caso del día resuelto! Racha: {0}", "Caso do dia resolvido! Sequência: {0}" },
            ["daily_again"] = new[] { "Already solved today. Come back tomorrow for a new case.", "Сегодня уже раскрыто. Приходи завтра за новым делом.", "Бүгін шешілді. Жаңа іс үшін ертең кел.", "Ya resuelto hoy. Vuelve mañana por un caso nuevo.", "Já resolvido hoje. Volte amanhã para um novo caso." },
            ["streak"] = new[] { "streak {0}", "серия {0}", "серия {0}", "racha {0}", "sequência {0}" },
            ["trophies"] = new[] { "TROPHIES", "ТРОФЕИ", "ЖЕТІСТІКТЕР", "TROFEOS", "TROFÉUS" },
            ["trophy_got"] = new[] { "Trophy: {0}  +{1} XP", "Трофей: {0}  +{1} опыта", "Жетістік: {0}  +{1} тәжірибе", "Trofeo: {0}  +{1} XP", "Troféu: {0}  +{1} XP" },
            ["tr.FirstBanish.name"] = new[] { "First banishing", "Первое изгнание", "Алғашқы қуу", "Primera expulsión", "Primeira expulsão" },
            ["tr.FirstBanish.desc"] = new[] { "Banish an entity.", "Изгони сущность.", "Тылсым күшті қу.", "Expulsa una entidad.", "Expulse uma entidade." },
            ["tr.Names10.name"] = new[] { "Name keeper", "Знаток имён", "Есім білгірі", "Conocedor de nombres", "Sabe os nomes" },
            ["tr.Names10.desc"] = new[] { "Name the entity correctly 10 times.", "Верно назови сущность 10 раз.", "Тылсым күштің атын 10 рет дұрыс ата.", "Nombra correctamente a la entidad 10 veces.", "Diga o nome certo da entidade 10 vezes." },
