            ["n.Static"] = new[] { "The camera is acting up…", "Камера барахлит…", "Камера ақаулана бастады…", "La cámara falla…", "A câmera está falhando…" },
            ["n.Compass"] = new[] { "Something electric in the air…", "В воздухе будто электричество…", "Ауада электр бар сияқты…", "Algo eléctrico en el aire…", "Algo elétrico no ar…" },
            ["n.NightVision"] = new[] { "Was something there?…", "Показалось?.. Там что-то было?", "Көзіме елестеді ме?.. Онда бірдеңе бар ма еді?", "¿Te lo pareció?… ¿Había algo ahí?", "Foi impressão?… Tinha algo ali?" },
            ["h.Frost"] = new[] { "Check with the thermal camera. Below zero — mark “Cold”.", "Проверь тепловизором. Ниже нуля — отметь «Холод».", "Тепловизормен тексер. Нөлден төмен болса — «Суық» белгіле.", "Compruébalo con la cámara térmica. Bajo cero: marca «Frío».", "Confira com a câmera térmica. Abaixo de zero: marque “Frio”." },
            ["h.Whisper"] = new[] { "Mark “Whisper” in the journal.", "Отметь в дневнике «Шёпот».", "Күнделікке «Сыбыр» белгіле.", "Marca «Susurro» en el diario.", "Marque “Sussurro” no diário." },
            ["h.Knock"] = new[] { "Mark “Knocking” in the journal.", "Отметь в дневнике «Стук».", "Күнделікке «Тықыл» белгіле.", "Marca «Golpes» en el diario.", "Marque “Batidas” no diário." },
            ["h.Static"] = new[] { "Sweep the camera around — where the picture tears, mark “Static”.", "Поводи камерой — где картинка рвётся, отметь «Помехи».", "Камераны айналдыр — сурет бұзылған жерде «Кедергі» белгіле.", "Recorre con la cámara: donde la imagen se rompa, marca «Interferencias».", "Percorra com a câmera — onde a imagem rasgar, marque “Chiado”." },
            ["h.Compass"] = new[] { "Point the EMF reader around. At 5 — mark “EMF 5”.", "Поводи ЭМП-детектором. На 5 — отметь «ЭМП 5».", "ЭМӨ-детекторды айналдыр. 5 болса — «ЭМӨ 5» белгіле.", "Recorre con el detector EMF. Si marca 5, anota «EMF 5».", "Percorra com o detector EMF. Em 5, marque “EMF 5”." },
            ["h.NightVision"] = new[] { "Turn on the night camera and look around. A silhouette — mark “Silhouette”.", "Включи ночную камеру и осмотрись. Силуэт — отметь «Силуэт».", "Түнгі камераны қосып, айналаңа қара. Сұлба көрінсе — «Сұлба» белгіле.", "Activa la cámara nocturna y mira alrededor. Si ves una silueta, marca «Silueta».", "Ligue a câmera noturna e olhe ao redor. Viu uma silhueta — marque “Silhueta”." },
            ["h.Radio"] = new[] { "Try the spirit box: turn it on and ask out loud “Are you here?”", "Попробуй радио духов: включи и спроси вслух «Ты здесь?»", "Рухтар радиосын қолданып көр: қос та, дауыстап «Сен мұндасың ба?» деп сұра.", "Prueba la radio de espíritus: enciéndela y pregunta «¿Estás aquí?»", "Experimente o rádio dos espíritos: ligue e pergunte “Você está aí?”" },
            ["h.RadioYes"] = new[] { "It answered — mark “Radio”.", "Ответило — отметь «Радио».", "Жауап берді — «Радио» белгіле.", "Respondió: marca «Radio».", "Respondeu — marque “Rádio”." },
            ["h.Journal"] = new[] { "You have seen enough signs. Open the journal → Clues, then name it.", "Знаков достаточно. Открой дневник → «Улики» и назови её.", "Белгілер жеткілікті. Күнделікті аш → «Дәлелдер», сосын атын ата.", "Ya has visto suficientes señales. Abre el diario → Pistas y nómbrala.", "Você já viu sinais suficientes. Abra o diário → Pistas e diga o nome." },
            ["new_presence"] = new[] { "Something unfamiliar is here… Gather clues and check the journal.", "Здесь что-то незнакомое… Собирай улики и сверяйся с дневником.", "Мұнда бейтаныс бірдеңе бар… Дәлел жина да, күнделікпен салыстыр.", "Aquí hay algo desconocido… Reúne pistas y consulta el diario.", "Há algo desconhecido aqui… Junte pistas e consulte o diário." },
            ["l.Photo.name"] = new[] { "Old photo", "Старая фотография", "Ескі сурет", "Foto antigua", "Foto antiga" },
            ["l.Photo.desc"] = new[] { "Draws ghosts and doppelgängers — those who remember a face.", "Привлекает призрака и двойника — тех, кто помнит лицо.", "Елес пен егізді тартады — бет-бейнені есте сақтайтындарды.", "Atrae a fantasmas y dobles: a quienes recuerdan un rostro.", "Atrai fantasmas e sósias — quem se lembra de um rosto." },
            ["l.Yarn.name"] = new[] { "Ball of yarn", "Клубок ниток", "Жіп орамы", "Ovillo de lana", "Novelo de lã" },
            ["l.Yarn.desc"] = new[] { "Draws the kikimora and the albasty — they spin and tangle hair.", "Привлекает кикимору и албасты — они прядут и путают волосы.", "Кикимора мен албастыны тартады — олар жіп иіріп, шаш шатастырады.", "Atrae a la kikimora y a la albasty: hilan y enredan el pelo.", "Atrai a kikimora e a albasty — elas fiam e embaraçam cabelos." },
            ["l.Meat.name"] = new[] { "Raw meat", "Сырое мясо", "Шикі ет", "Carne cruda", "Carne crua" },
            ["l.Meat.desc"] = new[] { "Draws the upyr and the poltergeist — the hungry and the violent.", "Привлекает упыря и полтергейста — голодных и буйных.", "Упырь мен полтергейстті тартады — аштар мен бұзақыларды.", "Atrae al upyr y al poltergeist: los hambrientos y los violentos.", "Atrai o upyr e o poltergeist — os famintos e os violentos." },
            ["l.MusicBox.name"] = new[] { "Music box", "Музыкальная шкатулка", "Әуен қорапшасы", "Caja de música", "Caixa de música" },
