            ["lure_no"] = new[] { "Silence. Not this one.", "Тишина. Не то.", "Тыныштық. Бұл емес.", "Silencio. No es esto.", "Silêncio. Não é isso." },
            ["h.LureYes"] = new[] { "It reacted — check the journal: which two does this lure draw?", "Откликнулась — посмотри в дневнике, кого из двоих привлекает эта приманка.", "Жауап берді — күнделіктен бұл жем қай екеуін тартатынын қара.", "Ha reaccionado: mira en el diario a cuáles dos atrae este cebo.", "Ela reagiu — veja no diário quais duas essa isca atrai." },
            ["h.Lure"] = new[] { "Not sure who it is? Try a lure from the bag.", "Не знаешь, кто это? Попробуй приманку из сумки.", "Кім екенін білмейсің бе? Сөмкеден жем қолданып көр.", "¿No sabes quién es? Prueba un cebo de la bolsa.", "Não sabe quem é? Experimente uma isca da bolsa." },
            ["h.Look"] = new[] { "Something draws your eyes… {0}", "Что-то тянет посмотреть… {0}", "Бірдеңе қарауға тартады… {0}", "Algo te hace mirar… {0}", "Algo puxa seu olhar… {0}" },
            ["h.Start"] = new[] { "Start with the darkest places — that is where they hide.", "Начни с самых тёмных мест — там они и прячутся.", "Ең қараңғы жерлерден баста — олар сонда жасырынады.", "Empieza por los sitios más oscuros: ahí se esconden.", "Comece pelos lugares mais escuros — é lá que se escondem." },
            ["n.Possessed"] = new[] { "Cold… That is not a person anymore.", "Холодный… Это уже не человек.", "Суп-суық… Бұл енді адам емес.", "Frío… Eso ya no es una persona.", "Frio… Isso já não é uma pessoa." },
            ["n.Animal"] = new[] { "The animal tenses up… It senses something {0}.", "Животное насторожилось… Оно чует что-то {0}.", "Жануар сескенді… Ол {0} бірдеңені сезеді.", "El animal se tensa… Percibe algo {0}.", "O animal fica tenso… Sente algo {0}." },
            ["ar"] = new[] { "AR mode", "Режим AR", "AR режимі", "Modo AR", "Modo AR" },
            ["ar_auto"] = new[] { "Auto", "Авто", "Авто", "Auto", "Auto" },
            ["ar_install"] = new[] { "Install AR", "Установить AR", "AR орнату", "Instalar AR", "Instalar AR" },
            ["ar_note"] = new[] { "Auto: AR only if Google Play Services for AR is already installed; otherwise gyro mode.", "Авто: AR, только если уже стоят сервисы Google Play для AR; иначе — режим гироскопа.", "Авто: AR тек Google Play AR қызметтері орнатылған болса; әйтпесе — гироскоп режимі.", "Auto: AR solo si los servicios de Google Play para AR ya están instalados; si no, giroscopio.", "Auto: AR só se os Serviços do Google Play para AR já estiverem instalados; senão, giroscópio." },
            ["ar_restart"] = new[] { "Restart the game — it will offer to install AR services.", "Перезапусти игру — она предложит установить сервисы AR.", "Ойынды қайта қос — ол AR қызметтерін орнатуды ұсынады.", "Reinicia el juego: te ofrecerá instalar los servicios de AR.", "Reinicie o jogo — ele vai oferecer a instalação dos serviços de AR." },
